insert into public.collections (id, name, slug, description, cover_image, display_order, active) values
  ('6a1b2c3d-0001-4000-8000-000000000001', 'Sci-Fi & Future', 'sci-fi-future', 'Armoured helmets, synthetic beings and deep-space explorers — futuristic busts with crisp panel lines and hard-surface detail.', '/images/collections/sci-fi-future-1200.webp', 1, true),
  ('6a1b2c3d-0001-4000-8000-000000000002', 'Gaming & Fantasy', 'gaming-fantasy', 'Warlords, knights and heroes of the realm — gaming-inspired fantasy busts built for bold display and dramatic paint schemes.', '/images/collections/gaming-fantasy-1200.webp', 2, true),
  ('6a1b2c3d-0001-4000-8000-000000000003', 'Horror & Dark Art', 'horror-dark-art', 'Demons, revenants and gothic nightmares — dark-art busts with deep recesses made for shadows, washes and weathering.', '/images/collections/horror-dark-art-1200.webp', 3, true),
  ('6a1b2c3d-0001-4000-8000-000000000004', 'Heroes & Legends', 'heroes-legends', 'Superhero-inspired champions and mythic legends — original designs with powerful poses and iconic silhouettes.', '/images/collections/heroes-legends-1200.webp', 4, true),
  ('6a1b2c3d-0001-4000-8000-000000000005', 'Original Creations', 'original-creations', 'Characters you will only find at BUSTLAB — our own original designs, from masked wanderers to brand-new worlds.', '/images/collections/original-creations-1200.webp', 5, true)
insert into public.products (id, name, slug, short_description, description, category_id, main_image, gallery_images, dimensions, material_description, ready_to_paint, featured, shopify_url, etsy_url, published, display_order, created_at) values
  ('6a1b2c3d-0002-4000-8000-000000000001', 'Vanguard Mk II', 'vanguard-mk-ii', 'An armoured sci-fi trooper helmet with a wraparound visor and layered shoulder plates.', 'The Vanguard Mk II is a hard-surface sci-fi bust built around a sculpted wraparound visor, side comms modules and a raised helmet crest. Layered pauldrons and a ribbed chin guard give painters plenty of panels to pick out — from clean military schemes to battle-worn weathering.', '6a1b2c3d-0001-4000-8000-000000000001', '/images/products/vanguard-mk-ii-1-1600.webp', array['/images/products/vanguard-mk-ii-2-1600.webp', '/images/products/vanguard-mk-ii-3-1600.webp']::text[], null, 'Supplied unpainted in a neutral finish, ready for priming and painting. Paints and tools are not included.', true, true, null, null, true, 1, '2026-01-02T00:00:00.000Z'),
  ('6a1b2c3d-0002-4000-8000-000000000002', 'Nova Unit-07', 'nova-unit-07', 'A sleek synthetic android with a segmented neck and armoured face plate.', 'Nova Unit-07 pairs smooth synthetic surfaces with mechanical detail: a segmented neck assembly, recessed optic band and sculpted sensor fins. A striking piece for metallic finishes, glowing optics or a pristine lab-white scheme.', '6a1b2c3d-0001-4000-8000-000000000001', '/images/products/nova-unit-07-1-1600.webp', array['/images/products/nova-unit-07-2-1600.webp', '/images/products/nova-unit-07-3-1600.webp']::text[], null, 'Supplied unpainted in a neutral finish, ready for priming and painting. Paints and tools are not included.', true, true, null, null, true, 2, '2026-01-03T00:00:00.000Z'),
  ('6a1b2c3d-0002-4000-8000-000000000003', 'Abyss Diver', 'abyss-diver', 'A heavy dome dive helmet with portholes, riveted collar and trailing hoses.', 'The Abyss Diver is a retro-futuristic dive helmet bust featuring three framed portholes, a riveted collar ring and sculpted air hoses. Ideal for brass and verdigris effects, rust and grime, or a sleek deep-space recolour.', '6a1b2c3d-0001-4000-8000-000000000001', '/images/products/abyss-diver-1-1600.webp', array['/images/products/abyss-diver-2-1600.webp', '/images/products/abyss-diver-3-1600.webp']::text[], null, 'Supplied unpainted in a neutral finish, ready for priming and painting. Paints and tools are not included.', true, true, null, null, true, 3, '2026-01-04T00:00:00.000Z'),
  ('6a1b2c3d-0002-4000-8000-000000000004', 'Iron Warden', 'iron-warden', 'A fantasy great-helm knight with layered pauldrons and a sculpted crest.', 'Iron Warden is a fantasy knight bust with a flat-topped great helm, pierced breathing holes, a tall crest and stacked pauldrons. Built for true-metal techniques, heraldic colours or a battered, mud-splattered finish.', '6a1b2c3d-0001-4000-8000-000000000002', '/images/products/iron-warden-1-1600.webp', array['/images/products/iron-warden-2-1600.webp', '/images/products/iron-warden-3-1600.webp']::text[], null, 'Supplied unpainted in a neutral finish, ready for priming and painting. Paints and tools are not included.', true, true, null, null, true, 4, '2026-01-05T00:00:00.000Z'),
  ('6a1b2c3d-0002-4000-8000-000000000005', 'Tuskborn Warchief', 'tuskborn-warchief', 'A tusked warlord with a spiked crest, fur mantle and spiked shoulder armour.', 'The Tuskborn Warchief is a gaming-inspired fantasy bust with a heavy brow, curved tusks, a spiked crest and a thick mantle across the shoulders. Plenty of texture for skin tones, fur and scarred armour.', '6a1b2c3d-0001-4000-8000-000000000002', '/images/products/tuskborn-warchief-1-1600.webp', array['/images/products/tuskborn-warchief-2-1600.webp', '/images/products/tuskborn-warchief-3-1600.webp']::text[], null, 'Supplied unpainted in a neutral finish, ready for priming and painting. Paints and tools are not included.', true, false, null, null, true, 5, '2026-01-06T00:00:00.000Z'),
  ('6a1b2c3d-0002-4000-8000-000000000006', 'Thornhorn', 'thornhorn', 'A horned demon bust with sweeping horns, spined back and spiked shoulders.', 'Thornhorn is a dark-art demon bust with sweeping tapered horns, a spined crest and ridged chest plating. Deep recesses make it perfect for dramatic shading, glowing eyes and fiery colour transitions.', '6a1b2c3d-0001-4000-8000-000000000003', '/images/products/thornhorn-1-1600.webp', array['/images/products/thornhorn-2-1600.webp', '/images/products/thornhorn-3-1600.webp']::text[], null, 'Supplied unpainted in a neutral finish, ready for priming and painting. Paints and tools are not included.', true, true, null, null, true, 6, '2026-01-07T00:00:00.000Z'),
  ('6a1b2c3d-0002-4000-8000-000000000007', 'The Revenant', 'the-revenant', 'A hooded gothic figure with a skull face and a heavy draped cloak.', 'The Revenant is a gothic horror bust featuring a deep hood framing a skull face, a draped cloak and a ringed clasp. A great canvas for bone tones, cloth highlights and atmospheric shadow work.', '6a1b2c3d-0001-4000-8000-000000000003', '/images/products/the-revenant-1-1600.webp', array['/images/products/the-revenant-2-1600.webp', '/images/products/the-revenant-3-1600.webp']::text[], null, 'Supplied unpainted in a neutral finish, ready for priming and painting. Paints and tools are not included.', true, false, null, null, true, 7, '2026-01-08T00:00:00.000Z'),
  ('6a1b2c3d-0002-4000-8000-000000000008', 'Lich Sovereign', 'lich-sovereign', 'A crowned undead sovereign with a spiked collar and ribbed chest.', 'The Lich Sovereign is an undead ruler bust with a spiked crown, a fan of collar spines and a ribbed chest. Suits aged bone, tarnished gold and eerie glow effects.', '6a1b2c3d-0001-4000-8000-000000000003', '/images/products/lich-sovereign-1-1600.webp', array['/images/products/lich-sovereign-2-1600.webp', '/images/products/lich-sovereign-3-1600.webp']::text[], null, 'Supplied unpainted in a neutral finish, ready for priming and painting. Paints and tools are not included.', true, false, null, null, true, 8, '2026-01-09T00:00:00.000Z'),
  ('6a1b2c3d-0002-4000-8000-000000000009', 'Aegis Paragon', 'aegis-paragon', 'An original winged-helm champion with a high cape collar and chest emblem.', 'Aegis Paragon is an original superhero-inspired bust with a winged helm, half-face mask, high cape collar and an angular chest emblem. Made for bold primary colours, metallic wings or your own hero design.', '6a1b2c3d-0001-4000-8000-000000000004', '/images/products/aegis-paragon-1-1600.webp', array['/images/products/aegis-paragon-2-1600.webp', '/images/products/aegis-paragon-3-1600.webp']::text[], null, 'Supplied unpainted in a neutral finish, ready for priming and painting. Paints and tools are not included.', true, false, null, null, true, 9, '2026-01-10T00:00:00.000Z'),
  ('6a1b2c3d-0002-4000-8000-000000000010', 'Masked Ronin', 'masked-ronin', 'An original masked wanderer with a lower face guard, headband and layered shoulder lames.', 'The Masked Ronin is a BUSTLAB original: a masked wanderer with a ridged face guard, tied headband, topknot and layered shoulder armour. Ideal for lacquered finishes, weathered cloth and fine freehand detail.', '6a1b2c3d-0001-4000-8000-000000000005', '/images/products/masked-ronin-1-1600.webp', array['/images/products/masked-ronin-2-1600.webp', '/images/products/masked-ronin-3-1600.webp']::text[], null, 'Supplied unpainted in a neutral finish, ready for priming and painting. Paints and tools are not included.', true, false, null, null, true, 10, '2026-01-11T00:00:00.000Z')
